473	
474	  // -------------------------------------------------------------------------
475	  // WORKER: listar "minhas lojas"
476	  // -------------------------------------------------------------------------
477	
478	  /**
479	   * Lista as conexões aceitas do worker autenticado ("minhas lojas").
480	   * Retorna conexões 'accepted' com perfil da empresa embutido.
481	   */
482	  async listMyStores(): Promise<MyStore[]> {
483	    try {
484	      const {
485	        data: { user },
486	      } = await supabase.auth.getUser();
487	      if (!user) return [];
488	
489	      const { data, error } = await supabase
490	        .from('team_connections')
491	        .select(
492	          `
493	          *,
494	          company:companies (
495	            id,
496	            name,
497	            logo_url,
498	            rating_average,
499	            reviews_count,
500	            industry,
501	            address
502	          )
503	        `,
504	        )
505	        .eq('worker_id', user.id)
506	        .eq('status', 'accepted')
507	        .order('accepted_at', { ascending: false });
508	
509	      if (error) {
510	        logError('teamConnection.listMyStores', error);
511	        return [];
512	      }
513	
514	      return ((data ?? []) as Array<TeamConnection & { company: CompanyProfile }>).map(
515	        (row) => ({
516	          connection: {
517	            id: row.id,
518	            company_id: row.company_id,
519	            worker_id: row.worker_id,
520	            status: row.status,
521	            source: row.source,
522	            blocked_by: row.blocked_by,
523	            created_at: row.created_at,
524	            accepted_at: row.accepted_at,
525	            updated_at: row.updated_at,
526	          },
527	          company: row.company,
528	        }),
529	      );
530	    } catch (err) {
531	      logError('teamConnection.listMyStores', err);
