569	      }
570	
571	      return (data ?? []) as TeamConnection[];
572	    } catch (err) {
573	      logError('teamConnection.listPendingConnections', err);
574	      return [];
575	    }
576	  },
577	
578	  // -------------------------------------------------------------------------
579	  // Validação: checar se um worker é da equipe aceita de uma empresa
580	  // -------------------------------------------------------------------------
581	
582	  /**
583	   * Retorna true se o worker for conexão 'accepted' da empresa.
584	   * Usado antes de criar um convite de turno (R5/ADR-001).
585	   */
586	  async isWorkerInTeam(companyId: string, workerId: string): Promise<boolean> {
587	    const { data, error } = await supabase
588	      .from('team_connections')
589	      .select('id')
590	      .eq('company_id', companyId)
591	      .eq('worker_id', workerId)
592	      .eq('status', 'accepted')
593	      .maybeSingle();
594	
595	    if (error) {
596	      logError('teamConnection.isWorkerInTeam', error);
597	      return false;
598	    }
599	
600	    return !!data;
601	  },
602	};
