1	/**
2	 * ShiftInviteService — convite push de turno (Slice 1, R5/R7/R8).
3	 *
4	 * Fluxo push: EMPRESA cria application com status='invited' para worker da equipe.
5	 * Fluxo de resposta: WORKER aceita ('accepted') ou recusa ('declined').
6	 *
7	 * Avisos do architect (ADR-001):
8	 * 1. A transição de status do convite (invited → accepted/declined) NÃO é forçada por RLS;
9	 *    validamos a máquina de estados AQUI no service.
10	 * 2. Recusa é NEUTRA (zero punição — R7): só muda status para 'declined'.
11	 * 3. Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
12	 *    accepted aqui = status 'hired' (confirmado no turno) SEM escrow. Slice 2 preenche o gap.
13	 * 4. inserts de review devem passar direction explicitamente — ver ReviewService em types/index.ts.
14	 */
15	
16	import { supabase } from '../lib/supabase';
17	import { invokeFunction } from './api';
18	import { logError } from '../lib/logger';
19	import { TeamConnectionService } from './teamConnectionService';
20	import type {
21	  Application,
22	  ApplicationStatus,
23	  InvitationResponse,
24	} from '../types';
25	
26	// ---------------------------------------------------------------------------
27	// Tipos de parâmetros e resultado
28	// ---------------------------------------------------------------------------
29	
30	/** Janela de expiração do convite em horas (R8). Default = 48h. */
31	const DEFAULT_INVITE_EXPIRY_HOURS = 48;
32	
33	export interface InviteWorkerToShiftOptions {
34	  /** Horas até o convite expirar (default: 48). */
35	  expiresInHours?: number;
36	  /** Mensagem personalizada para a notificação (opcional). */
37	  message?: string;
38	}
39	
40	export interface InviteWorkerResult {
41	  application: Application | null;
42	  error?: string;
43	  /** true quando já existe um convite pendente (idempotência). */
44	  alreadyInvited?: boolean;
45	}
46	
47	export interface RespondToInviteResult {
48	  success: boolean;
49	  error?: string;
50	}
51	
52	// ---------------------------------------------------------------------------
53	// Helpers internos
54	// ---------------------------------------------------------------------------
55	
56	/** Obtém o company_id da sessão autenticada (empresa). */
57	async function getAuthCompanyId(): Promise<string> {
58	  const {
59	    data: { user },
60	  } = await supabase.auth.getUser();
61	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
62	
63	  const { data: company, error } = await supabase
64	    .from('companies')
65	    .select('id')
66	    .eq('owner_id', user.id)
67	    .maybeSingle();
68	
