/**
 * Gera (ou reutiliza) um token de convite de link para a empresa atual.
 *
 * Estratégia: o token é o `company_id` codificado em base64url + timestamp truncado,
 * suficiente para o MVP (não requer tabela separada de tokens).
 * A UI monta a URL: `https://app.worki.com/convite/{token}`.
 * O resolver do link chama `resolveInviteToken(token)` para descobrir a empresa.
 */
generateInviteToken(companyId: string): ConnectionInviteToken {
  // Token simples, não criptográfico — o RLS protege o DB; o token só identifica a empresa.
  const payload = `${companyId}:${Date.now()}`;
  const token = btoa(payload).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
  const url = `${window.location.origin}/convite/${token}`;
  return { token, url };
},

/**
 * Resolve um token de link de convite → retorna o `company_id`.
 * Retorna null se o token for inválido ou malformado.
 */
resolveInviteToken(token: string): string | null {
  try {
    const padded = token.replace(/-/g, '+').replace(/_/g, '/');
    const payload = atob(padded);
    const [companyId] = payload.split(':');
    if (!companyId || companyId.length < 30) return null;
    return companyId;
  } catch {
    return null;
  }
},

