/**
 * Adiciona um worker via token de link de convite.
 * A empresa é extraída do token; o worker aceita a conexão no próximo passo.
 */
async addToTeamByToken(
  token: string,
  workerId: string,
): Promise<CreateConnectionResult> {
  const companyId = this.resolveInviteToken(token);
  if (!companyId) {
    return { connection: null, error: 'Link de convite inválido ou expirado.' };
  }

  // Inserir a conexão diretamente (o worker dispara isso via link)
  // O RLS de INSERT exige que company_id IN companies WHERE owner_id = auth.uid().
  // Aqui o worker não é dono da company → não pode usar a policy de empresa.
  // Solução: o link de convite é resolvido pela EMPRESA (ela abre o link no seu contexto)
  // OU a inserção usa invokeFunction para uma Edge Function se precisarmos do worker-side.
  // Para o MVP, o fluxo de link abre na sessão da empresa → addToTeam normal.
  // Se o fluxo for "worker clica no link" → vira uma pending da empresa pendente de iniciativa.
  // No MVP v1, o link é enviado pela empresa para o worker fora do app; o worker aceita depois.
  // Registro da conexão: a empresa cria pending via addToTeam; o worker aceita via acceptConnection.
  // Esta função é um helper de conveniência para testes e fluxos alternativos.
  const { data: company, error: cErr } = await supabase
    .from('companies')
    .select('id, owner_id')
    .eq('id', companyId)
    .single();

  if (cErr || !company) {
    return { connection: null, error: 'Empresa do convite não encontrada.' };
  }

  // Verificar existência
  const { data: existing } = await supabase
    .from('team_connections')
    .select('*')
    .eq('company_id', companyId)
    .eq('worker_id', workerId)
    .maybeSingle();

  if (existing) {
    return { connection: existing as TeamConnection, alreadyExists: true };
  }

  const { data, error } = await supabase
    .from('team_connections')
    .insert({
      company_id: companyId,
      worker_id: workerId,
      status: 'pending' as TeamConnectionStatus,
      source: 'link' as TeamConnectionSource,
    })
    .select()
    .single();

  if (error) {
    if (error.code === '23505') {
      return { connection: null, alreadyExists: true };
    }
    logError('teamConnection.addToTeamByToken.insert', error);
    return { connection: null, error: 'Não foi possível registrar o convite.' };
  }

  return { connection: data as TeamConnection };
},

